string decodeString(string s) {
    vector<pair<string,int>> st; string cur; int num = 0;
    for (char c : s) {
        if (isdigit(c)) num = num * 10 + (c - '0');
        else if (c == '[') { st.push_back({cur, num}); cur.clear(); num = 0; }
        else if (c == ']') { auto [prev, k] = st.back(); st.pop_back(); string r = prev; for (int i = 0; i < k; i++) r += cur; cur = r; }
        else cur += c;
    }
    return cur;
}
